'use strict';
/* Latin phrase book for the games, part 2 (see gametr-la.js). */
Object.assign(GT_BOOKS.la.lines, {
"But listen: it does not sing. {p} has locked its voice away in <b>Castle Unwritten</b>, in the {p} far to the north-east.": "Sed audī: nōn canit. {p} vōcem eius in <b>Castellō Nōn Scrīptō</b> inclūsit, in {p} procul ad septentriōnēs et orientem.",
"The castle gate opens only for three keys, hidden long ago at the edges of the world:": "Porta castellī sōlum tribus clāvibus aperītur, ōlim in fīnibus orbis cēlātīs:",
"🪶 the <b>Dawn Quill</b>, high in the {p} in the north,": "🪶 <b>Pennā Aurōrae</b>, altē in {p} ad septentriōnēs,",
"🫙 the <b>Dusk Inkwell</b>, lost in the {p} in the south,": "🫙 <b>Ātrāmentāriō Vesperī</b>, āmissō in {p} ad merīdiem,",
"⭐ and the <b>Star Seal</b>, fallen into the {p} in the far south.": "⭐ et <b>Sigillō Stellārum</b>, quod in {p} procul ad merīdiem cecidit.",
"I have ordered the old roads opened: north and south of Aldermere, north and south of Seravel. Your ship can sail north and south from the Eastern Isles too.": "Vīās veterēs aperīrī iussī: ad septentriōnēs et merīdiem Aldermerī, ad septentriōnēs et merīdiem Seravēlī. Nāvis tua quoque ab Īnsulīs Orientālibus ad septentriōnēs et merīdiem nāvigāre potest.",
"Ask in the taverns. People remember more than they think. Go, and bring back our words!": "In caupōnīs quaere. Hominēs plūs meminērunt quam putant. Ī, et verba nostra refer!",
"{p}: All three keys! Castle Unwritten is in the {p}, far to the north-east. End this, hero.": "{p}: Omnēs trēs clāvēs! Castellum Nōn Scrīptum in {p} est, procul ad septentriōnēs et orientem. Hoc fīnī, hērōs.",
"✨ Something glints between the rocks… you dig it out.": "✨ Aliquid inter saxa micat… id effodis.",
"🪶 You found the <b>Dawn Quill</b>! A golden quill that writes light. (Key {n} of {n})": "🪶 <b>Pennam Aurōrae</b> invēnistī! Penna aurea quae lūcem scrībit. (Clāvis {n} ex {n})",
"✨ Deep in the trees, a little pool of shadow… no, an inkwell, sitting on a mossy stone.": "✨ Altē inter arborēs, parvus lacus umbrae… immō ātrāmentārium, in saxō muscōsō positum.",
"🫙 You found the <b>Dusk Inkwell</b>! Its ink is the color of the evening sky. (Key {n} of {n})": "🫙 <b>Ātrāmentārium Vesperī</b> invēnistī! Ātrāmentum eius colōrem caelī vespertīnī habet. (Clāvis {n} ex {n})",
"✨ Something in the dust of the gully twinkles like a fallen star.": "✨ Aliquid in pulvere vallis ut stēlla lapsa micat.",
"⭐ You found the <b>Star Seal</b>! A silver seal shaped like a star. (Key {n} of {n})": "⭐ <b>Sigillum Stellārum</b> invēnistī! Sigillum argenteum stēllae fōrmā. (Clāvis {n} ex {n})",
"🔑 The quill, the inkwell and the star hum together in your bag.": "🔑 Penna, ātrāmentārium et stēlla in saccō tuō simul sonant.",
"Castle Unwritten’s gate will open for you now. It stands in the {p}, in the far north-east.": "Porta Castellī Nōn Scrīptī nunc tibi aperiētur. In {p} stat, procul ad septentriōnēs et orientem.",
"The cave floor is a frozen lake. Under the ice, two cold eyes open.": "Solum spēluncae lacus gelātus est. Sub glaciē duo oculī frīgidī aperiuntur.",
"A wyrm of ice smashes up through the floor!": "Dracō glaciēī per solum ērumpit!",
"{p} shatters into a thousand glittering pieces.": "{p} in mīlle partēs fulgentēs frangitur.",
"Wind howls up the shaft. A giant bird made of storm clouds lands in front of you.": "Ventus per puteum ululat. Avis ingēns ex nūbibus tempestātis facta ante tē cōnsīdit.",
"{p}: SKREEEEE!": "{p}: SKRĪĪĪĪ!",
"{p} dissolves into a harmless spring rain.": "{p} in pluviam vernam innocuam solvitur.",
"A skeleton in a scholar’s robe looks up from a book of black pages.": "Sceletus vestīmentō doctī ē librō pāginārum nigrārum suspicit.",
"{p}: Ah, visitors. Let me write you… an ending.": "{p}: Ā, hospitēs. Sinite mē vōbīs… fīnem scrībere.",
"{p}’s book slams shut, and he crumbles to dust with it.": "Liber {p} subitō clauditur, et ille cum eō in pulverem collābitur.",
"The temple floor cracks. Vines as thick as trees rise up, each with a snapping head.": "Solum templī findītur. Vītēs crassae ut arborēs surgunt, singulae cum capite mordentī.",
"{p} hisses from three mouths at once!": "{p} ex tribus ōribus simul sībilat!",
"{p} withers and sinks back into the ground.": "{p} marcēscit et in terram redit.",
"The water in the barrow bubbles. A huge shape of mud and weeds rises, wearing a crown of reeds.": "Aqua in tumulō fervet. Fōrma ingēns lutī et algae surgit, corōnam harundinum gerēns.",
"{p}: You are tracking mud into my palace!": "{p}: Lutum in palātium meum fertis!",
"{p} slumps back into a harmless puddle. Her crown floats away.": "{p} in lacūnam innocuam collābitur. Corōna eius abnatat.",
"Hot wind fills the cave. A red wyvern drops from the ceiling, wings spread wide.": "Ventus calidus spēluncam implet. Wyverna rubra ē tēctō dēscendit, ālīs lātē passīs.",
"{p} roars, and the whole canyon roars with it!": "{p} rugit, et tōta vallis cum eō rugit!",
"{p} flees out of a crack in the rock, never to return.": "{p} per rīmam saxī fugit, numquam reditūra.",
"💰 {p} guarded a pile of treasure!": "💰 {p} acervum thēsaurī custōdiēbat!",
"💰 {p}’s nest is full of shiny things!": "💰 Nīdus {p} rērum nitidārum plēnus est!",
"💰 {p}’s hoard is yours!": "💰 Thēsaurus {p} tuus est!",
"💰 Treasure hidden among the roots!": "💰 Thēsaurus inter rādīcēs cēlātus!",
"💰 {p}’s treasure, a little muddy.": "💰 Thēsaurus {p}, paulum lutulentus.",
"💰 The wyvern’s hoard glitters in the dark!": "💰 Thēsaurus wyvernae in tenebrīs fulget!",
"The three keys rise out of your bag and fit into the sockets.": "Trēs clāvēs ē saccō surgunt et in forāmina intrant.",
"With a sound like a book opening, Castle Unwritten’s gate swings wide.": "Sonō ut liber apertus, porta Castellī Nōn Scrīptī lātē aperītur.",
"You pull the {p} lever. Its flame goes out.": "Vectem {p} trahis. Flamma eius exstinguitur.",
"🔥 Sun, star… and the moon asleep. The iron gate grinds upward!": "🔥 Sōl, stēlla… et lūna dormiēns. Porta ferrea sursum strīdet!",
"✨ The plate glows.": "✨ Tabula lūcet.",
"The plates sink back into the floor with a groan.": "Tabulae cum gemitū in solum redeunt.",
"Read the poem again: in what order does the night pass?": "Carmen iterum lege: quō ōrdine nox trānsit?",
"🔥 All four plates blaze with light. The iron gate grinds upward!": "🔥 Omnēs quattuor tabulae lūce ārdent. Porta ferrea sursum strīdet!",
"🗿 {p}: “Answer my word, traveler.”": "🗿 {p}: “Verbō meō respondē, viātor.”",
"🗿 {p}: “True words.” Its eyes glow gold.": "🗿 {p}: “Vēra verba.” Oculī eius aureī lūcent.",
"🗿 {p}: “Not true. Come back when you know.”": "🗿 {p}: “Nōn vērum. Redī cum scīveris.”",
"🗿 All three statues glow. The great doors to the throne room swing open!": "🗿 Omnēs trēs statuae lūcent. Magnae forēs ātriī soliī aperiuntur!",
"Welcome to {p}. The King awaits brave souls.": "Salvē in {p}. Rēx animōs fortēs exspectat.",
"{p}’s last guards block the stairs!": "Ultimī custōdēs {p} gradūs claudunt!",
"Keep warm! The {p} Wolves hunt in packs out on the tundra.": "Calidus manē! Lupī {p} gregātim in campīs gelidīs vēnantur.",
"East of here the land turns to rock and thunder: the {p}.": "Ad orientem hinc terra fit saxum et tonitrus: {p}.",
"I built a snow knight yesterday. It has a sword made of an icicle!": "Heri equitem nivālem fēcī. Gladium ex stīriā factum habet!",
"Thunder Hawks steal our hats. Every. Single. Day.": "Accipitrēs tonitrūs pilleōs nostrōs rapiunt. Omnī. Diē.",
"Further east the land goes black. Nothing grows in the {p}.": "Ulterius ad orientem terra nigrēscit. Nihil in {p} crēscit.",
"The mine’s gold paid for this town. Now monsters dig there instead.": "Aurum metallī hoc oppidum aedificāvit. Nunc mōnstra ibi fodiunt.",
"We are the last town before the castle. Buy {p}: the wraiths out there love curses.": "Ultimum oppidum ante castellum sumus. {p} eme: larvae illīc maledictiōnēs amant.",
"The Blighted Crypt is north-west of here. A Lich Scribe writes death verses down there.": "Crypta Tābida ad septentriōnēs et occidentem hinc est. Scrība Mortuus ibi versūs mortis scrībit.",
"Mum says not to look at the castle at night. I looked. It looked back.": "Māter dīcit nē castellum noctū spectem. Spectāvī. Mē respexit.",
"Vine Serpents bite. Carry Antidotes, always.": "Serpentēs vītis mordent. Semper antidota fer.",
"North is Aldermere. East is the {p}. Mind your boots.": "Ad septentriōnēs est Aldermerum. Ad orientem {p}. Calceōs tuōs cūrā.",
"A parrot taught me a rude word. I won’t say it.": "Psittacus mē verbum turpe docuit. Nōn dīcam.",
"Rot Caps puff poison. Hold your breath. Or just bring Antidotes.": "Fungī putridī venēnum efflant. Animam tenē. Aut antidota fer.",
"The road north goes back up to Seravel, through the canyon road.": "Via ad septentriōnēs ad Seravēlum redit, per viam vallis.",
"I caught a frog the size of my head! Then it caught me.": "Rānam capite meō maiōrem cēpī! Deinde illa mē cēpit.",
"The sea north of here leads back to the Eastern Isles, if you have a boat.": "Mare ad septentriōnēs ad Īnsulās Orientālēs redit, sī nāvem habēs.",
"Sun Scarabs flash so bright you can’t see. Squint!": "Scarabaeī sōlis tam clārē fulgent ut vidēre nōn possīs. Oculōs contrahe!",
"Yell in the canyon and it yells back. I yelled my name forty times.": "Clāmā in valle, et illa respondet. Nōmen meum quadrāgiēs clāmāvī.",
"The way ahead is guarded!": "Via ante tē custōdītur!",
"The Hoarfrost Cavern is north-east of town. Something huge sleeps in the ice down there.": "Spēlunca Pruīnae ad septentriōnēs et orientem oppidī est. Aliquid ingēns ibi in glaciē dormit.",
"The old road south goes back to Aldermere. The King opened it for you, they say.": "Via vetus ad merīdiem ad Aldermerum redit. Rēx eam tibi aperuit, ut dīcunt.",
"Pray, rest, and be brave. {p} fears words spoken with courage.": "Ōrā, requiēsce, fortis estō. {p} verba fortiter dicta timet.",
"The Dawn Quill? A shepherd swore she saw a golden glint on the peak above the old mine, in the north-west.": "Penna Aurōrae? Pāstor iūrāvit sē fulgōrem aureum in vertice suprā metallum vetus vīdisse, ad septentriōnēs et occidentem.",
"The Thunder Mine runs deep. A Storm Roc nests at the bottom.": "Metallum Tonitrūs altē patet. Avis Tempestātis in īmō nīdificat.",
"Castle Unwritten is east of town. Its gate has three sockets: a quill, an inkwell and a star.": "Castellum Nōn Scrīptum ad orientem oppidī est. Porta eius tria forāmina habet: pennam, ātrāmentārium et stēllam.",
"Inside the castle, the old guards say, the doors only open for the clever. Levers, plates and talking statues.": "In castellō, ut veterēs custōdēs dīcunt, forēs sōlum sollertibus aperiuntur. Vectēs, tabulae et statuae loquentēs.",
"The Dusk Inkwell? Old Ma {p} talks about a grove nobody can find, deep in the trees in the south-east.": "Ātrāmentārium Vesperī? Vetula {p} dē lūcō dīcit quem nēmō invenīre potest, altē inter arborēs ad merīdiem et orientem.",
"The Overgrown Temple is north-east. A Vine Hydra grew out of the floor in there!": "Templum Obrutum ad septentriōnēs et orientem est. Hydra Vītium ibi ex solō crēvit!",
"The Drowned Barrow is south-west of town, past the reeds. {p} rules it.": "Tumulus Mersus ad merīdiem et occidentem oppidī est, ultrā harundinēs. {p} eī imperat.",
"The canyon east of here is dry as bone. Opposite of here, really.": "Vallis ad orientem hinc sicca ut os est. Contrāria huic locō, rē vērā.",
"The Star Seal? There’s a gully in the far west, past the red cliffs, where the stars fall at night.": "Sigillum Stellārum? Vallis angusta est procul ad occidentem, ultrā rūpēs rubrās, ubi stēllae noctū cadunt.",
"The Echo Canyon Caves are south-east. A Canyon Wyvern roosts at the bottom.": "Spēluncae Vallis Echūs ad merīdiem et orientem sunt. Wyverna Vallis in īmō habitat.",
"🪨 Words are carved into the stone:": "🪨 Verba in lapide incīsa sunt:",
"“Wake the Sun and the Star, but let the Moon sleep.”": "“Excitā Sōlem et Stēllam, sed sine Lūnam dormīre.”",
"“Beware: every lever stirs the one beside it.”": "“Cavē: omnis vectis eum quī iuxtā est movet.”",
"Two Ink Sentinels step out of the shadows!": "Duo Excubitōrēs ātrāmentī ex umbrīs prōdeunt!",
"🪨 A poem is carved into the stone:": "🪨 Carmen in lapide incīsum est:",
"“First the quill writes the dawn, then the sun climbs high,”": "“Prīmum penna aurōram scrībit, deinde sōl altē ascendit,”",
"“the moon follows after, and a star closes the sky.”": "“lūna posteā sequitur, et stēlla caelum claudit.”",
"Four plates are set into the floor: 🪶 ☀️ 🌙 ⭐": "Quattuor tabulae in solō positae sunt: 🪶 ☀️ 🌙 ⭐",
"The Statue of Dawn": "Statua Aurōrae",
"The Statue of Noon": "Statua Merīdiēī",
"The Statue of Dusk": "Statua Vesperī",
"🪨 “Speak true words to the three statues, and the last door will open.”": "🪨 “Vēra verba tribus statuīs dīc, et ultima porta aperiētur.”",
"{p}: Rare goods from across the sea! Take a look.": "{p}: Mercēs rārae trāns mare! Aspice.",
"{p}: Blades and bows from faraway smithies!": "{p}: Gladiī et arcūs ē fabricīs longinquīs!",
"Welcome to {p}, the west harbor of Aldermere! Ships come and go all day.": "Salvē in {p}, portū occidentālī Aldermerī! Nāvēs tōtum diem veniunt et abeunt.",
"Sail north along the coast and you reach the {p}. South takes you to the jungle.": "Secundum ōram ad septentriōnēs nāvigā, et ad {p} perveniēs. Ad merīdiem ad silvās dēnsās ībis.",
"There’s a shrine on a little island just south of here. Sailors pray there before a long trip.": "In īnsulā parvā prope hinc ad merīdiem sacellum est. Nautae ibi ante longum iter ōrant.",
"{p} never freezes. The sea keeps moving, so the ice can’t catch it.": "{p} numquam congelāscit. Mare semper movētur, itaque glaciēs id capere nōn potest.",
"East along the north coast is the Thundercrag shore, and past that, the black Inkblight sea.": "Ad orientem secundum ōram septentriōnālem est lītus Montium Tonantium, et ultrā, mare nigrum Vastitātis Ātrāmentī.",
"An island shrine sits just off the coast, north of here. Ice all around it, but warm inside.": "Sacellum in īnsulā prope ōram stat, ad septentriōnēs hinc. Glaciēs circum, sed intus calidum.",
"{p}! Best fish on the whole continent. Don’t tell the Marsh folk I said that.": "{p}! Optimī piscēs tōtīus continentis. Nōlī palūdānīs dīcere mē hoc dīxisse.",
"You can sail up the river from here, right into the heart of the jungle.": "Hinc in flūmen nāvigāre potes, in medium silvārum.",
"East along the coast is {p}, then the red canyon. The whole south shore is one long sea road.": "Ad orientem secundum ōram est {p}, deinde vallis rubra. Tōtum lītus merīdiānum ūna longa via maris est.",
"{p} sits where the marsh meets the sea. Mind the eels at low tide.": "{p} stat ubi palūs mare tangit. Anguillās cavē cum aestus recēdit.",
"The sea lanes go all the way round the continent now that the King opened them.": "Viae maris nunc circum tōtam continentem eunt, quia Rēx eās aperuit.",
"Old story: there’s a shrine out on the water, east of here, that heals even the fallen.": "Fābula vetus: sacellum in aquā est, ad orientem hinc, quod etiam cadūcōs sānat.",
"Every coast of the continent is linked by sea now. Sail all the way round if you like!": "Omnis ōra continentis nunc marī iungitur. Circum tōtam nāvigā, sī vīs!",
"Island shrines heal the whole crew. Steer close and pray from the deck.": "Sacella īnsulārum tōtam turbam nautārum sānant. Propius gubernā et ē nāve ōrā.",
"I pray here before every voyage. The sea is kinder to the faithful.": "Hīc ante omne iter ōrō. Mare fīdēlibus benignius est.",
"{p}: Welcome to our home, young hero. Do look around. The library is my favourite room.": "{p}: Salvē in domō nostrā, hērōs iuvenis. Circumspice. Bibliothēca camera mihi cārissima est.",
"{p}: The cook makes the best honey bread in the kingdom. Tell him I sent you.": "{p}: Coquus optimum pānem mellītum in rēgnō facit. Dīc eī mē tē mīsisse.",
"{p}: Stand tall before the King!": "{p}: Rēctus stā ante Rēgem!",
"{p}: Nobody gets near the thrones without our say-so.": "{p}: Nēmō ad solia appropinquat sine nostrā veniā.",
"{p}: One day I’ll go on an adventure too! Father says I must learn my words first.": "{p}: Ōlim ego quoque iter magnum faciam! Pater dīcit mē prīmum verba mea discere dēbēre.",
"{p}: Did you know there are chests in three colors? Ruby, sapphire and emerald. Each needs its own key.": "{p}: Scīsne arcās tribus colōribus esse? Rubīneās, sapphīrīnās, smaragdīnās. Quaeque clāvem suam requīrit.",
"{p}: Shh! This is the royal library. Every book here was written with the old {p}.": "{p}: St! Haec bibliothēca rēgia est. Omnis liber hīc vetere {p} scrīptus est.",
"{p}: Read a little every day and the words will stay with you.": "{p}: Cotīdiē paulum lege, et verba tēcum manēbunt.",
"{p}: I’m supposed to be dusting the shelves… but this book about sea monsters is really good.": "{p}: Pluteōs pūrgāre dēbeō… sed hic liber dē mōnstrīs marīnīs vērē bonus est.",
"{p}: Mind the hot stove! Honey bread for the King, stew for the guards.": "{p}: Fornācem calidam cavē! Pānis mellītus Rēgī, iūs custōdibus.",
"{p}: Hungry? Inns are the place for a hot meal and a warm bed.": "{p}: Ēsurīs? In caupōnīs cēna calida et lectus calidus sunt.",
"{p}: Twelve loaves, six pies and a cake for the Prince. And the day has only started!": "{p}: Duodecim pānēs, sex crustula et placenta Prīncipī. Et diēs modo coepit!",
"{p}: Night shift tonight. I’m resting my feet while I can.": "{p}: Hāc nocte vigilō. Pedēs requiēscō dum possum.",
"{p}: My guards keep the towns safe. If you see a pickpocket, call for us!": "{p}: Custōdēs meī oppida tūta servant. Sī fūrem vidēs, nōs vocā!",
"{p}: Every town has a jail now. Thieves spend a night behind bars, or pay a fine.": "{p}: Omne oppidum nunc carcerem habet. Fūrēs noctem in carcere agunt, aut poenam solvunt.",
"{p}: Father keeps the Ruby Key in the treasury, downstairs on this side.": "{p}: Pater Clāvem Rubīneam in aerāriō servat, īnfrā, hāc parte.",
"{p}: {p} of Seravel keeps the Sapphire Key. And the Emerald Key? Lost at sea, somewhere far to the south-east.": "{p}: {p} Seravēlī Clāvem Sapphīrīnam servat. Et Clāvis Smaragdīna? In marī āmissa, alicubi procul ad merīdiem et orientem.",
"{p}: The Princess’s room must be spotless. She notices every speck of dust!": "{p}: Cubiculum Prīncipissae pūrissimum esse dēbet. Omnem pulverem animadvertit!",
"{p}: The royal dinner is at sundown. Forty guests, sixty candles.": "{p}: Cēna rēgia sōle occidente est. Quadrāgintā hospitēs, sexāgintā candēlae.",
"{p}: Taxes, letters, maps… a chancellor’s work is never done.": "{p}: Vectīgālia, epistulae, tabulae… opus cancellāriī numquam fīnītur.",
"{p}: I came all the way from {p} for the feast. Isn’t the hall lovely?": "{p}: Ā {p} ad convīvium vēnī. Nōnne ātrium pulchrum est?",
"{p}: The King says you may open the treasury chests. The Ruby Key is in the locked one.": "{p}: Rēx dīcit tē arcās aerāriī aperīre posse. Clāvis Rubīnea in arcā clausā est.",
"{p}: Spell its word to open the lock. Then the key opens every ruby-red chest you find.": "{p}: Verbum eius scrībe ut claustrum aperiās. Deinde clāvis omnem arcam rubīneam quam invenīs aperit.",
"{p}: Good day! The great hall gets so dusty with all these visitors.": "{p}: Salvē! Magnum ātrium tot hospitibus tam pulverulentum fit.",
"{p}: Welcome to {p}. The King is at the far end of the hall.": "{p}: Salvē in {p}. Rēx in extrēmō ātriō est.",
"{p}: The town is just outside. Enjoy your visit!": "{p}: Oppidum prope forīs est. Vīsitātiōne fruere!",
"{p}: My mother rules Seravel from this throne. I’m learning to sail, so I can visit every coast!": "{p}: Māter mea ex hōc soliō Seravēlō imperat. Nāvigāre discō, ut omnēs ōrās vīsitem!",
"{p}: The Sapphire Key? It’s in our treasury, of course. Ask the guard there.": "{p}: Clāvis Sapphīrīna? In aerāriō nostrō est, scīlicet. Custōdem ibi rogā.",
"{p}: Bow to Her Majesty, {p}!": "{p}: Rēgīnae sē inclīnā, {p}!",
"{p}: The sun never sets on Seravel. Well… it does. But slowly.": "{p}: Sōl numquam in Seravēlō occidit. Immō… occidit. Sed lentē.",
"{p}: These shelves hold maps of every coast and island. The seas link all the way round now!": "{p}: Hī pluteī tabulās omnium ōrārum et īnsulārum tenent. Maria nunc circum tōtum orbem iunguntur!",
"{p}: Old charts say the Emerald Key sank with a ship near an island in the south-east.": "{p}: Tabulae veterēs dīcunt Clāvem Smaragdīnam cum nāve prope īnsulam ad merīdiem et orientem mersam esse.",
"{p}: I am copying a map of the Sunken Archive. One wrong line and someone gets lost!": "{p}: Tabulam Tabulāriī Mersī dēscrībō. Ūna līnea prāva, et aliquis errat!",
"{p}: Spiced rice, date cakes and mint tea. Palace food is the best in the desert!": "{p}: Oryza condīta, placentae palmulārum et thea menthae. Cibus palātiī optimus in dēsertō est!",
"{p}: Try not to steal from the townsfolk. The jail food is terrible, I hear.": "{p}: Nōlī ab oppidānīs fūrārī. Cibus carceris pessimus est, ut audiō.",
"{p}: Fresh oranges from the oasis! The Queen loves them.": "{p}: Māla aurantia recentia ex oasī! Rēgīna ea amat.",
"{p}: Sand in my boots again. Sand everywhere!": "{p}: Harēna iterum in calceīs. Harēna ubīque!",
"{p}: My guards watch the market. Pickpockets end up in the town jail.": "{p}: Custōdēs meī forum spectant. Fūrēs in carcerem oppidī veniunt.",
"{p}: Pay the fine, or work it off with honest words. Your choice.": "{p}: Poenam solve, aut verbīs honestīs eam solve labōrandō. Tuum est.",
"{p}: A ruby chest, a sapphire chest, an emerald chest… a key for each color. Once you have a key, it’s yours for good.": "{p}: Arca rubīnea, arca sapphīrīna, arca smaragdīna… clāvis prō quōque colōre. Cum clāvem habēs, tua est in perpetuum.",
"{p}: I saw a blue sapphire chest in the desert once. Maybe you’ll find it!": "{p}: Ōlim arcam sapphīrīnam caeruleam in dēsertō vīdī. Fortasse eam inveniēs!",
"{p}: The Princess wants her blue silk ready for the feast.": "{p}: Prīncipissa sēricum caeruleum ad convīvium parātum vult.",
"{p}: The dining hall is ready for the ambassadors from Aldermere.": "{p}: Trīclīnium lēgātīs Aldermerī parātum est.",
"{p}: Every ship that sails the Royal dock brings news from across the sea.": "{p}: Omnis nāvis quae ad nāvāle rēgium nāvigat nūntiōs trāns mare fert.",
"{p}: I bring greetings from {p}. What a beautiful palace!": "{p}: Salūtem ā {p} ferō. Quam pulchrum palātium!",
"{p}: The Queen allows you into the treasury. The Sapphire Key is in the word-locked chest.": "{p}: Rēgīna tē in aerārium admittit. Clāvis Sapphīrīna in arcā claustrō verbī clausā est.",
"{p}: Spell its word, and every sapphire-blue chest in the world will open for you.": "{p}: Verbum eius scrībe, et omnis arca sapphīrīna in orbe tibi aperiētur.",
"{p}: Mind the carpet, it’s freshly brushed!": "{p}: Tapētem cavē, modo pūrgātum est!",
"{p}: Welcome to {p}. Her Majesty is at the end of the hall.": "{p}: Salvē in {p}. Rēgīna in extrēmō ātriō est.",
"{p}: {p} is right outside. Ships leave from the Royal dock.": "{p}: {p} prope forīs est. Nāvēs ā nāvālī rēgiō proficīscuntur.",
"{p}: I only borrowed a loaf of bread! Honest!": "{p}: Pānem tantum mūtuātus sum! Vērē!",
"{p}: Forty years I picked pockets. Then I picked the Captain’s. Big mistake.": "{p}: Quadrāgintā annōs saccōs surripuī. Deinde saccum Ducis. Magnus error.",
"{p}: Keep your hands in your own pockets and you’ll never see the inside of a cell.": "{p}: Manūs in saccīs tuīs tenē, et numquam cellam ab intus vidēbis.",
"The roads north and south of the old kingdoms are open again. Strange lands out there!": "Viae ad septentriōnēs et merīdiem rēgnōrum veterum iterum apertae sunt. Terrae mīrae illīc!",
"Some treasures are hidden in plain sight. Walk where nobody walks.": "Quīdam thēsaurī in apertō cēlantur. Ambulā ubi nēmō ambulat.",
"The whole continent is ringed by sea. With a ship you can reach every coast.": "Tōta continēns marī cingitur. Nāve ad omnem ōram pervenīre potes.",
"Island shrines! Sail up close and pray from your boat.": "Sacella īnsulārum! Propius nāvigā et ē nāve ōrā.",
"Watch your purse in the market! There are pickpockets about.": "In forō marsupium cavē! Fūrēs adsunt.",
"Every town has a jail now. Thieves get a night behind bars.": "Omne oppidum nunc carcerem habet. Fūrēs noctem in carcere agunt.",
"Have you seen the colored chests? Ruby, sapphire, emerald… each wants its own key.": "Vīdistīne arcās colōrātās? Rubīneam, sapphīrīnam, smaragdīnam… quaeque clāvem suam vult.",
"A smooth, frosted pebble of glass. Worth {n} gold at any shop.": "Calculus vitrī lēvis et gelidus. {n} aureōrum in quāvīs tabernā.",
"Hold it to your ear and hear the sea. Worth {n} gold.": "Ad aurem tenē et mare audī. {n} aureōrum.",
"A sailor’s ring, a little tarnished. Worth {n} gold.": "Ānulus nautae, paulum obscūrātus. {n} aureōrum.",
"A perfect round pearl. Worth {n} gold.": "Margarīta rotunda et perfecta. {n} aureōrum.",
"A tiny statue carved from red coral. Worth {n} gold.": "Parva statua ex corallō rubrō sculpta. {n} aureōrum.",
"A pouch of old pirate coins. Worth {n} gold.": "Sacculus nummōrum pīrāticōrum veterum. {n} aureōrum.",
"A crown from a kingdom lost to the sea. Worth {n} gold.": "Corōna rēgnī quod mare cēpit. {n} aureōrum.",
"A deep blue gem with a star inside. Worth {n} gold.": "Gemma caerulea cum stēllā intus. {n} aureōrum.",
"Snow and fallen rock block the way.": "Nix et saxa lapsa viam claudunt.",
"{p} may know how to open the old roads north and south.": "{p} fortasse scit quōmodo viae veterēs ad septentriōnēs et merīdiem aperiantur.",
"Thick black fog hangs over the sea to the north.": "Nebula nigra et dēnsa super mare ad septentriōnēs pendet.",
"{p} may know what lies beyond it.": "{p} fortasse scit quid ultrā sit.",
"A wall of storms blocks the southern sea.": "Mūrus tempestātum mare merīdiānum claudit.",
"Black gates as tall as trees. Three empty sockets glow faintly in the stone:": "Portae nigrae altae ut arborēs. Tria forāmina vacua in lapide leviter lūcent:",
"a quill, an inkwell and a star. Without all three keys, the castle will not open.": "penna, ātrāmentārium et stēlla. Sine omnibus tribus clāvibus castellum nōn aperiētur.",
"Storms block the open sea.": "Tempestātēs mare apertum claudunt.",
"{p} may know when the old sea lanes open.": "{p} fortasse scit quandō veterēs viae maris aperiantur.",
"You found something!": "Aliquid invēnistī!",
"🔑 You got the <b>{p}</b>! 🔴": "🔑 <b>{p}</b> accēpistī! 🔴",
"🔑 You got the <b>{p}</b>! 🔵": "🔑 <b>{p}</b> accēpistī! 🔵",
"🔑 You got the <b>{p}</b>! 🟢": "🔑 <b>{p}</b> accēpistī! 🟢",
"It opens every ruby chest in the world, and it stays with you for good.": "Omnem arcam rubīneam in orbe aperit, et tēcum in perpetuum manet.",
"It opens every sapphire chest in the world, and it stays with you for good.": "Omnem arcam sapphīrīnam in orbe aperit, et tēcum in perpetuum manet.",
"It opens every emerald chest in the world, and it stays with you for good.": "Omnem arcam smaragdīnam in orbe aperit, et tēcum in perpetuum manet.",
"🔴 A ruby chest! Its keyhole is shaped like a ruby.": "🔴 Arca rubīnea! Forāmen clāvis fōrmam rubīnī habet.",
"🔵 A sapphire chest! Its keyhole is shaped like a sapphire.": "🔵 Arca sapphīrīna! Forāmen clāvis fōrmam sapphīrī habet.",
"🟢 A emerald chest! Its keyhole is shaped like a emerald.": "🟢 Arca smaragdīna! Forāmen clāvis fōrmam smaragdī habet.",
"It only opens with the <b>{p}</b>.": "Sōlum <b>{p}</b> aperītur.",
"The {p} is kept in the treasury of {p}.": "{p} in aerāriō {p} servātur.",
"The {p} is kept in the treasury of {p}, in {p}.": "{p} in aerāriō {p} servātur, in {p}.",
"Old charts say the {p} lies on a far island in the south-east sea.": "Tabulae veterēs dīcunt {p} in īnsulā longinquā maris merīdiānī et orientālis iacēre.",
"🔑 The {p} turns with a click… 🔴": "🔑 {p} cum sonitū vertitur… 🔴",
"🔑 The {p} turns with a click… 🔵": "🔑 {p} cum sonitū vertitur… 🔵",
"🔑 The {p} turns with a click… 🟢": "🔑 {p} cum sonitū vertitur… 🟢",
"🚨 A guard makes you pay {n} gold back. Behave yourself!": "🚨 Custōs tē {n} aureōs reddere cōgit. Bene tē gere!",
"🔒 Clang! The cell door slams shut behind you.": "🔒 Clang! Iānua cellae post tē clauditur.",
"Talk to the {p} through the bars to get out.": "Cum {p} per clātrōs loquere ut exeās.",
"You pay {n} gold.": "{n} aureōs solvis.",
"🔓 Clank! The cell door swings open.": "🔓 Clank! Iānua cellae aperītur.",
"{p}: Off you go. And stay out of other folks’ pockets!": "{p}: Abī. Et ā saccīs aliēnīs abstinē!",
"{p}: Visiting? Keep your hands in your own pockets and you’ll never stay here.": "{p}: Vīsitās? Manūs in saccīs tuīs tenē, et numquam hīc manēbis.",
"👮 {p}: “Caught with your hand in a pocket, eh?” · 💰 {n}": "👮 {p}: “Manū in saccō aliēnō captus es, ita?” · 💰 {n}",
"💰 Pay the fine ({n} gold)": "💰 Poenam solve ({n} aureī)",
"🧽 Scrub the floors (answer {n} words right)": "🧽 Solum pūrgā ({n} verba rēctē respondē)",
"Honest work, honest words.": "Opus honestum, verba honesta.",
"⏳ Wait": "⏳ Exspectā",
"You sit on the cold stone floor. Nobody comes to let you out.": "In frīgidō solō lapideō sedēs. Nēmō venit ut tē līberet.",
"✨ The floors are sparkling!": "✨ Solum splendet!",
"{p}: Not bad. Not bad at all.": "{p}: Nōn male. Nōn male omnīnō.",
"🧽 Scrubbing the floor… {n}/{n}": "🧽 Solum pūrgās… {n}/{n}",
"{p}: Missed a spot! Keep going.": "{p}: Locum praetermīsistī! Perge.",
"💬 Talk": "💬 Loquere",
"🤏 Pick their pocket": "🤏 Saccum eius surripe",
"They’re watching you now.": "Nunc tē spectat.",
"Their pockets are empty now.": "Saccī eius nunc vacuī sunt.",
"A guard is watching! Move away first.": "Custōs spectat! Prīmum abī.",
"Listen for the word and pick it. Wrong means jail!": "Verbum audī et ēlige. Error carcerem significat!",
"🤏 Sneaky… which word do you hear?": "🤏 Callidē… quod verbum audīs?",
"{p}: “Hey! THIEF!”": "{p}: “Heus! FŪR!”",
"🚨 A town guard grabs you by the collar!": "🚨 Custōs oppidī tē collō capit!",
"Off to the jail you go…": "In carcerem abīs…",
"🤫 Your fingers slip into their pocket…": "🤫 Digitī tuī in saccum eius lābuntur…",
"💰 <b>{n} gold</b>! {p} didn’t notice a thing.": "💰 <b>{n} aureī</b>! {p} nihil sēnsit.",
"{p} {p} ×{n} · {n} gold each": "{p} {p} ×{n} · {n} aureī singulī",
"Sells one. All {n} are worth {n} gold.": "Ūnum vendit. Omnēs {n} {n} aureōrum sunt.",
"You sold the {p} for 💰 {n} gold.": "{p} vendidistī prō 💰 {n} aureīs.",
"💰 Sell treasures · you have 💰 {n} gold": "💰 Thēsaurōs vende · 💰 {n} aureōs habēs",
"💰 Sell everything ({n} gold)": "💰 Omnia vende ({n} aureī)",
"Sold! 💰 +{n} gold.": "Vēnditum! 💰 +{n} aureī.",
"💰 Sell treasures": "💰 Thēsaurōs vende",
"Your deck’s language. Menus, battles and the story in it. Names stay the same.": "Lingua fasciculī tuī. Tabulae, pugnae et fābula in eā. Nōmina manent.",
"Menus, battles and the story in this language. Your cards stay as they are.": "Tabulae, pugnae et fābula in hāc linguā. Chartae tuae manent ut sunt.",
"“How can I help?”<br>": "“Quid tibi faciam?”<br>",
"“Deposited {n} gold.”<br>": "“{n} aureī dēpositī.”<br>",
"“Withdrew {n} gold.”<br>": "“{n} aureī dēprōmptī.”<br>",
"“Your savings earned {n} gold in interest!”<br>": "“Pecūnia tua {n} aureōs faenoris meruit!”<br>",
"💰 With you: {n} · 🏦 In the bank: {n} · 📈 {n}% interest every {n} steps you travel": "💰 Tēcum: {n} · 🏦 In argentāriā: {n} · 📈 {n}% faenoris post {n} gradūs itineris",
"💰 Deposit everything": "💰 Omnia dēpōne",
"💰 Deposit half": "💰 Dīmidium dēpōne",
"💰 Deposit {n}": "💰 {n} dēpōne",
"🪙 Take out everything": "🪙 Omnia dēprōme",
"🪙 Take out half": "🪙 Dīmidium dēprōme",
"🪙 Take out {n}": "🪙 {n} dēprōme",
"Your gold is safe with us, in every town.": "Aurum tuum apud nōs tūtum est, in omnī oppidō.",
"Gold in the bank is safe, even if your whole party falls. The monsters can’t touch it!": "Aurum in argentāriā tūtum est, etiam sī omnēs comitēs cadunt. Mōnstra id tangere nōn possunt!",
"Nobody gets into the vault. Not even me!": "Nēmō in thēsaurum intrat. Nē ego quidem!",
"👥 Your party is full ({n}). <b>{p}</b> wants to come along. Swap someone out?": "👥 Comitēs plēnī sunt ({n}). <b>{p}</b> tēcum venīre vult. Aliquem mūtāsne?",
"Swap out {p}. Swap back at any tavern, shrine or camp.": "{p} mūtā. In quāvīs caupōnā, sacellō aut castrīs rūrsus mūtā.",
"🪑 {p} waits for now": "🪑 {p} nunc exspectat",
"Bring them along later at a tavern, shrine or camp.": "Posteā eum in caupōnā, sacellō aut castrīs addūc.",
"{p} will wait for you. Swap at any tavern, shrine or camp.": "{p} tē exspectābit. In quāvīs caupōnā, sacellō aut castrīs mūtā.",
"{p} joins the party! {p} will wait for you.": "{p} comitibus sē iungit! {p} tē exspectābit.",
"🛕 The shrine’s light glows. Your waiting friends could meet you here.": "🛕 Lūx sacellī lūcet. Amīcī tuī exspectantēs hīc tē convenīre possunt.",
"Friends waiting: {n}": "Amīcī exspectantēs: {n}",
"👥 Who travels with you? ({n} at most)": "👥 Quis tēcum iter facit? ({n} ad summum)",
"Travels with you. Pick to have them wait.": "Tēcum iter facit. Ēlige ut exspectet.",
"Waiting. Pick to bring along.": "Exspectat. Ēlige ut tēcum dūcās.",
"Your party is full: have someone wait first.": "Comitēs plēnī sunt: prīmum aliquem exspectāre iubē.",
"{p} will wait at the shrines.": "{p} in sacellīs exspectābit.",
"{p} will wait at camp.": "{p} in castrīs exspectābit.",
"A shadow sweeps over the ground… something huge is coming down out of the clouds!": "Umbra super terram trānsit… aliquid ingēns ē nūbibus dēscendit!",
"🎈 A red-and-white airship drops anchor right beside you.": "🎈 Nāvis āeria rubra et alba ancoram iuxtā tē iacit!",
"Ahoy down there! The Archmage sent word that the {p}’s heroes needed wings. Meet the <b>Wordwing</b>!": "Heus, vōs īnfrā! Summa Maga nūntiāvit hērōēs {p} ālīs egēre. Ecce <b>Āla Verbī</b>!",
"She flies over mountains, forests and seas. Land anywhere you like. Fewer monsters bother you up here… but watch for anything with wings.": "Super montēs, silvās et maria volat. Ubi vīs dēscende. Pauciōra mōnstra hīc sūrsum tē vexant… sed quidquid ālās habet cavē.",
"🎈 Open the menu and choose <b>Land here</b> to land, or <b>Call the airship</b> to fly again.": "🎈 Tabulam aperī et <b>Hīc dēscende</b> ēlige ut dēscendās, aut <b>Nāvem āeriam vocā</b> ut iterum volēs.",
"“And I’m a fair hand with a lance. Want me along?”": "“Et hastā satis bene pugnō. Vīsne mē tēcum?”",
"🔱 Yes, welcome aboard!": "🔱 Ita, cōnscende!",
"Then I’ll wait at camp and in the taverns. Call on me any time.": "Tum in castrīs et in caupōnīs exspectābō. Mē quandōcumque vocā.",
"🔱 <b>{p} the {p}</b> joined the party!": "🔱 <b>{p} {p}</b> comitibus sē iūnxit!",
"🎈 You can’t land here. Find a clear patch of ground.": "🎈 Hīc dēscendere nōn potes. Locum apertum quaere.",
"🛬 The Wordwing settles down gently. Everyone climbs out.": "🛬 Āla Verbī lēniter cōnsīdit. Omnēs exeunt.",
"🎈 The Wordwing swoops down and you climb aboard. Up you go!": "🎈 Āla Verbī dēvolat et cōnscendis. Sūrsum!",
"🎈 The Wordwing swoops down and lifts you off the {p}. Up you go!": "🎈 Āla Verbī dēvolat et tē dē {p} tollit. Sūrsum!",
"🌫️ Only clouds and endless sky that way. The captain turns the airship around.": "🌫️ Illīc sōlum nūbēs et caelum sine fīne. Dux nāvem āeriam vertit.",
"🛬 Land here": "🛬 Hīc dēscende",
"🎈 Call the airship": "🎈 Nāvem āeriam vocā",
"⛺ Make camp": "⛺ Castra pōne",
"🎤 Spoken spells: on": "🎤 Carmina dicta: sīc",
"🎤 Spoken spells: off": "🎤 Carmina dicta: nōn",
"Healing and protecting spells are cast by saying the word out loud. Off: type it instead.": "Carmina sānantia et tegentia verbō clārē dictō fīunt. Nōn: id scrībe.",
"✨ {p} casts <b>{p}</b>! Say this word:": "✨ {p} <b>{p}</b> canit! Hoc verbum dīc:",
"🎤 Speak": "🎤 Loquere",
"⏹ Stop": "⏹ Siste",
"I heard:": "Audīvī:",
"Try again!": "Iterum temptā!",
"👂 Listening… say it now": "👂 Audiō… nunc dīc",
"Say the word out loud.": "Verbum clārē dīc.",
"⌨️ Type it instead": "⌨️ Id scrībe",
"⛺ You pitch the tents and light a fire. Your companions settle in around it.": "⛺ Tabernācula pōnis et ignem accendis. Comitēs tuī circum eum cōnsīdunt.",
"Talk to them, play some music, or rest by the fire. Walk out of the clearing to break camp.": "Cum eīs loquere, mūsicam lūde, aut prope ignem requiēsce. Ex silvā exī ut castra moveās.",
"🪑 Stay at camp (wait)": "🪑 In castrīs manē (exspectā)",
"They’ll wait at camps, taverns and shrines.": "In castrīs, caupōnīs et sacellīs exspectābunt.",
"🎵 Ask for a song (🪕 lute)": "🎵 Carmen rogā (🪕 testūdō)",
"🎵 Ask for a song (🪈 wooden flute)": "🎵 Carmen rogā (🪈 tībia lignea)",
"🎵 Ask for a song (🎶 reed pipes)": "🎵 Carmen rogā (🎶 fistula)",
"🎵 Ask for a song (🥁 hand drum)": "🎵 Carmen rogā (🥁 tympanum)",
"{p} plays a little tune on the lute. 🎶": "{p} carmen parvum testūdine canit. 🎶",
"{p} plays a little tune on the wooden flute. 🎶": "{p} carmen parvum tībiā ligneā canit. 🎶",
"{p} plays a little tune on the reed pipes. 🎶": "{p} carmen parvum fistulā canit. 🎶",
"{p} plays a little tune on the hand drum. 🎶": "{p} carmen parvum tympanō canit. 🎶",
"<b>{p}</b> · waiting at camp": "<b>{p}</b> · in castrīs exspectat",
"🚶 Travel with me": "🚶 Mēcum iter fac",
"Your party is full: ask someone to stay first.": "Comitēs plēnī sunt: prīmum aliquem manēre rogā.",
"Join the party again.": "Comitibus rūrsus tē iunge.",
"I’ll keep the fire warm.": "Ignem calidum servābō.",
"Let’s go!": "Eāmus!",
"🔥 The campfire crackles.": "🔥 Ignis castrōrum crepitat.",
"😴 Rest until morning": "😴 Ad māne requiēsce",
"Everyone gets back all their HP and MP, and the poison is gone. The game is saved.": "Omnēs omnia PV et PM recipiunt, et venēnum abit. Lūdus servātur.",
"🏕️ Break camp": "🏕️ Castra movē",
"Sit a while": "Paulum sedē",
"You all fall asleep to the sound of the fire…": "Omnēs ad sonum ignis obdormītis…",
"☀️ Good morning! Everyone is rested and ready.": "☀️ Salvē, māne est! Omnēs requiēvērunt et parātī sunt.",
"A curse still lingers. A priest or Holy water will lift it.": "Maledictiō adhūc manet. Sacerdōs aut aqua sacra eam tollet.",
"A cozy tent. Somebody snores inside.": "Tabernāculum commodum. Aliquis intus stertit.",
"I grew up in the archive of {p}. My first word was “index”. My mother still tells everyone.": "In tabulāriō {p} crēvī. Prīmum verbum meum “index” erat. Māter adhūc omnibus nārrat.",
"I write down every new word we hear on the road. One day I want to write a dictionary of my own.": "Omne verbum novum quod in viā audīmus scrībō. Ōlim dictiōnārium meum scrībere volō.",
"When the Unwriter erased the old books, I cried for a week. Then I picked up my quill and decided to fight back.": "Cum Dēlētor librōs veterēs dēlēvit, hebdomadem flēvī. Deinde pennam cēpī et resistere cōnstituī.",
"Thank you for letting me come along. Books taught me about the world, but you showed it to me.": "Grātiās quod mē tēcum venīre sīvistī. Librī mē dē mundō docuērunt, sed tū eum mihi ostendistī.",
"I sang in the choir of {p} until my voice cracked at the big festival. Everyone laughed. I practiced for a whole year after that.": "In chorō {p} canēbam dōnec vōx mea in magnā fēstīvitāte frācta est. Omnēs rīsērunt. Tōtum annum posteā exercuī.",
"Songs remember words longer than people do. That’s why my hymns can heal: they carry old, kind words.": "Carmina verba diūtius quam hominēs meminērunt. Ideō hymnī meī sānant: verba vetera et benigna ferunt.",
"My grandmother taught me this lute. She said a song is just a word that refused to sit still.": "Avia mea mē hanc testūdinem docuit. Dīxit carmen esse verbum quod quiēscere nōluit.",
"When this is over, I want to travel to every town and learn one song from each.": "Cum hoc fīnītum erit, ad omne oppidum īre volō et ab ūnō quōque carmen ūnum discere.",
"I learned to shoot by knocking apples off trees for my little sisters. Now they want me to teach them.": "Sagittāre didicī māla dē arboribus sorōribus parvīs dēiciēns. Nunc volunt ut eās doceam.",
"The forest is never quiet. Listen long enough and you can hear it talk.": "Silva numquam tacet. Satis diū audī, et eam loquentem audiēs.",
"I left home because the monsters were coming closer every year. I wanted to meet them before they met my family.": "Domō abiī quia mōnstra omnī annō propius veniēbant. Ea convenīre voluī antequam familiam meam convenīrent.",
"Out here, under the stars, I feel like I can hear every word the wind has ever said.": "Hīc, sub stēllīs, sentiō mē omne verbum audīre quod ventus umquam dīxit.",
"At the monastery we spent a whole year saying only one word a day. Mine was “patience”. I didn’t like it at first.": "In monastēriō tōtum annum ūnum tantum verbum cotīdiē dīcēbāmus. Meum erat “patientia”. Prīmō mihi nōn placuit.",
"My hands heal because I’m calm. When I’m angry, nothing works. Funny, isn’t it?": "Manūs meae sānant quia tranquillus sum. Cum īrātus sum, nihil valet. Rīdiculum, nōnne?",
"I walked out of the desert with nothing but my sandals. Everything else I own, you’ve seen me get on this journey.": "Ē dēsertō exiī nihil nisi soleās habēns. Cētera quae habeō mē in hōc itinere accipientem vīdistī.",
"Breathe in, breathe out. Tomorrow’s battle is tomorrow’s. Tonight is for the fire.": "Spīritum dūc, spīritum ēmitte. Pugna crāstina crāstina est. Haec nox ignis est.",
"Yes, I used to pick pockets. No, I don’t anymore. Well… mostly.": "Ita, ōlim saccōs surripiēbam. Nōn, iam nōn. Immō… ferē.",
"My father was a locksmith. He said every lock is just a question waiting for the right answer.": "Pater meus faber claustrōrum erat. Dīxit omne claustrum esse quaestiōnem quae rēctum respōnsum exspectat.",
"I joined you because the Unwriter took something from me: my real name. Nobody remembers it now. Not even me.": "Tibi mē iūnxī quia Dēlētor aliquid mihi ēripuit: nōmen meum vērum. Nēmō id nunc meminit. Nē ego quidem.",
"If we win, maybe I’ll find my name again. Until then, “{p}” will do.": "Sī vincimus, fortasse nōmen meum iterum inveniam. Intereā “{p}” satis est.",
"I took my oath at fifteen. My knees still hurt from kneeling all night in that chapel.": "Iūs iūrandum quīndecim annōs nātus iūrāvī. Genua mea adhūc dolent ex tōtā nocte in illō sacellō.",
"A shield isn’t for hiding. It’s for standing in front of someone who can’t stand alone.": "Scūtum nōn est ad latendum. Est ad standum ante aliquem quī sōlus stāre nōn potest.",
"I lost my best friend to a monster near the Ember Cave. I fight so nobody else has to say goodbye like that.": "Amīcum optimum mōnstrō prope Spēluncam Fāvillae āmīsī. Pugnō ut nēmō alius sīc valedīcere dēbeat.",
"You remind me of him. Brave, a little reckless. Don’t worry, I’ll keep my shield up for you.": "Mē eius admonēs. Fortis, paulum temerārius. Nōlī timēre, scūtum prō tē tenēbō.",
"I grew up in the treetops of the {p}. I didn’t walk on flat ground until I was eight.": "In summīs arboribus {p} crēvī. Ante octāvum annum in terrā plānā nōn ambulāvī.",
"Every plant has a name, and every name has a story. Moss is my favourite. It never gives up.": "Omnis planta nōmen habet, et omne nōmen fābulam. Muscus mihi cārissimus est. Numquam dēsistit.",
"The blight in the north is killing the old forests. That’s why I left my grove to join you.": "Pestis in septentriōnibus silvās veterēs necat. Ideō lūcum meum relīquī ut tibi mē iungerem.",
"Listen… the fire is crackling in the old tongue. It says we’ll be fine.": "Audī… ignis linguā antīquā crepitat. Dīcit nōbīs bene futūrum esse.",
"My first potion turned my eyebrows green for a month. My teacher said it was the best mistake she’d ever seen.": "Prīma pōtiō mea supercilia mea per mēnsem viridia fēcit. Magistra mea dīxit optimum errōrem esse quem umquam vīdisset.",
"Mixing potions is like making sentences. The right ingredients in the right order, or it all goes BOOM.": "Pōtiōnēs miscēre est ut sententiās facere. Rēctae rēs rēctō ōrdine, aut omnia BUM faciunt.",
"I study the Unwriter’s ink. If I can understand how it erases words, maybe I can make an ink that brings them back.": "Ātrāmentum Dēlētōris studeō. Sī intellegō quōmodo verba dēleat, fortasse ātrāmentum facere possum quod ea reddat.",
"Here, try this tea. It’s… mostly safe.": "Ecce, hanc theam gustā. Est… ferē tūta.",
"I was born on a sky ship. My crib was a hammock between two clouds.": "In nāve caelestī nātus sum. Cūnae meae lectus pēnsilis inter duās nūbēs erant.",
"The Wordwing was my mother’s ship. She taught me to fly before I could spell my own name.": "Āla Verbī nāvis mātris meae erat. Mē volāre docuit antequam nōmen meum scrībere poteram.",
"From up high, the whole world looks like one big sentence. Roads are the lines, towns are the words.": "Ex altō tōtus mundus ut ūna magna sententia vidētur. Viae līneae sunt, oppida verba.",
"When this is over, I’ll fly you anywhere you want. Free of charge. Well, maybe one sandwich.": "Cum hoc fīnītum erit, tē quōcumque vīs vehām. Grātīs. Immō, fortasse ūnō pāne fartō.",
"🌫️ Fog rolls over the water… A ship with torn grey sails drifts out of it. No one is at the wheel. Lanterns glow green on deck.": "🌫️ Nebula super aquam volvitur… Nāvis vēlīs cinereīs scissīs ex eā prōdit. Nēmō gubernāculum tenet. Lanternae in pontē viridēs lūcent.",
"👻 Board the ghost ship": "👻 Nāvem larvālem cōnscende",
"⛵ Sail away quickly": "⛵ Celeriter abnāvigā",
"You steer away. When you look back, the fog and the ship are gone.": "Abnāvigās. Cum respicis, nebula et nāvis abiērunt.",
"You tie the {p} alongside and climb up the slimy ladder…": "{p} iuxtā alligās et per scālās lūbricās ascendis…",
"👻 The deck creaks. Somewhere below, someone is laughing. Walk off the gangplank (bottom) to leave.": "👻 Pōns strīdet. Alicubi īnfrā aliquis rīdet. Per tabulam (īnfrā) exī ut abeās.",
"A ghostly lock holds the chest shut. The Captain’s curse, maybe?": "Claustrum larvāle arcam claudit. Maledictiō Ducis, fortasse?",
"👻 Ghosts rise from the deck!": "👻 Larvae ē ponte surgunt!",
"Who dares climb aboard MY ship? Hands off my treasure!": "Quis in MEAM nāvem ascendere audet? Manūs ā thēsaurō meō!",
"Stew… there is always stew… nobody eats it…": "Iūs… semper iūs est… nēmō id edit…",
"The Captain keeps the good loot in his cabin. Left side. Mind his temper.": "Dux praedam bonam in cubiculō suō servat. Parte laevā. Īram eius cavē.",
"You step into the ruins. Dust and old magic hang in the air.": "In ruīnās ingrederis. Pulvis et magia vetus in āere pendent.",
"📜 {p}. Something precious is sealed behind the far door.": "📜 {p}. Aliquid pretiōsum post portam extrēmam clausum est.",
"The plaque is cracked with ice:": "Tabula glaciē findītur:",
"“Four fires once burned for the Hero. Light them all, and the door will remember.”": "“Quattuor ignēs ōlim prō Hērōe ārdēbant. Omnēs accende, et porta meminerit.”",
"(Each brazier you touch flips itself and its neighbours.)": "(Quodque foculum quod tangis sē et vīcīna mūtat.)",
"Vines cover the old plaque:": "Vītēs tabulam veterem tegunt:",
"“Three stones keep three words. Wake them all without a single mistake.”": "“Trēs lapidēs tria verba servant. Omnēs excitā sine ūllō errōre.”",
"(Spell the word each stone asks for. One wrong word puts them all to sleep again.)": "(Verbum quod quisque lapis rogat scrībe. Ūnum verbum prāvum omnēs rūrsus sōpit.)",
"Sand has worn the letters almost smooth:": "Harēna litterās paene lēvēs trīvit:",
"“First the sun climbs. Then the stars wake. The moon follows them, and at last the sea swallows all.”": "“Prīmum sōl ascendit. Deinde stēllae expergīscuntur. Lūna eās sequitur, et tandem mare omnia dēvorat.”",
"You touch the brazier.": "Foculum tangis.",
"All four fires roar at once!": "Omnēs quattuor ignēs simul rugiunt!",
"🔓 The frozen door melts away.": "🔓 Porta gelāta liquēscit.",
"All four fires burn bright. The door is open.": "Omnēs quattuor ignēs clārē ārdent. Porta aperta est.",
"🗿 The stone whispers a meaning… spell the word": "🗿 Lapis significātiōnem susurrat… verbum scrībe",
"✨ The stone wakes up. {n} of {n} are awake.": "✨ Lapis expergīscitur. {n} ex {n} vigilant.",
"This stone is already awake.": "Hic lapis iam vigilat.",
"The stone goes cold… and every stone falls asleep again!": "Lapis frīgēscit… et omnēs lapidēs rūrsus obdormiunt!",
"Start over from the first stone you like.": "Ā quōvīs lapide rūrsus incipe.",
"All three stones blaze with green light!": "Omnēs trēs lapidēs lūce viridī ārdent!",
"🔓 With a deep grinding sound, the sealed door slides open.": "🔓 Gravī strīdōre porta clausa aperītur.",
"The stones glow quietly. The door is already open.": "Lapidēs quiētē lūcent. Porta iam aperta est.",
"🌀 A huge whirlpool spins under the ship! Deep below, something glows.": "🌀 Vertex ingēns sub nāve volvitur! Altē īnfrā aliquid lūcet.",
"🫧 Dive in": "🫧 Immerge tē",
"Sail around it": "Circum eum nāvigā",
"You take a deep breath and let the whirlpool pull you down…": "Spīritum altē dūcis et vorticem tē dēorsum trahere sinis…",
"🫧 A bubble of air wraps around your heads. You can breathe!": "🫧 Bulla āeris capita vestra circumdat. Spīrāre potestis!",
"Welcome to the Coral Kingdom.": "Salvē in Rēgnō Corallī.",
"A surface-dweller, in my kingdom? The whirlpool must have liked you.": "Incola terrae, in rēgnō meō? Vertex tē amāvisse dēbet.",
"We are in trouble. A great beast, the <b>Abyssal Leviathan</b>, has woken in the trench to the east. It eats our gardens and frightens our children.": "In perīculō sumus. Bēstia magna, <b>Leviathan Abyssī</b>, in fossā ad orientem expergīscitur. Hortōs nostrōs dēvorat et līberōs nostrōs terret.",
"Defeat it, and I will give you the treasure of our kingdom.": "Eam vince, et tibi thēsaurum rēgnī nostrī dabō.",
"Bow before {p}, lord of the deep!": "Sē inclīnā ante {p}, dominum profundī!",
"The trench is to the east. Past the kelp. Only the brave go there.": "Fossa ad orientem est. Ultrā algās. Sōlī fortēs eō eunt.",
"You have LEGS! Do they itch? They look itchy.": "CRŪRA habēs! Prūriuntne? Prūrīre videntur.",
"The bubble charm lets you breathe down here. Don’t take it off!": "Amulētum bullae tē hīc īnfrā spīrāre sinit. Nōlī id dēpōnere!",
"Sell your pearls in any harbor town. Humans love them.": "Margarītās tuās in quōvīs oppidō portūs vende. Hominēs eās amant.",
"Herbs from the sea garden. Very fresh. Very wet.": "Herbae ex hortō maris. Valdē recentēs. Valdē ūmidae.",
"You did it! The trench is quiet, and my people can swim freely again.": "Fēcistī! Fossa quiēta est, et populus meus iterum līberē natāre potest.",
"Take the <b>{p}</b>, forged from the coral of the first reef. And a little treasure for the road.": "<b>{p}</b> cape, ex corallō prīmī scopulī fabricātum. Et parvum thēsaurum prō viā.",
"The deep sings your name now, surface-friend. The Tidecaller is yours forever.": "Profundum nunc nōmen tuum canit, amīce terrae. Tridēns Maris tuus est in perpetuum.",
"The water goes dark and cold. Two huge eyes open in the deep.": "Aqua obscūra et frīgida fit. Duo oculī ingentēs in profundō aperiuntur.",
"⚠️ {p} uncoils from the trench!": "⚠️ {p} ē fossā sē explicat!",
"The Leviathan sinks back into the trench and does not rise again.": "Leviathan in fossam redit nec iterum surgit.",
"Return to {p} in the Coral Kingdom.": "Ad {p} in Rēgnō Corallī redī.",
"🫧 The current carries you up, up, up… and you pop out next to the {p}!": "🫧 Flūmen tē sūrsum, sūrsum, sūrsum fert… et prope {p} ēmergis!",
"🪦 {p}. The air is cold here.": "🪦 {p}. Āēr hīc frīgidus est.",
"Welcome to the {p}. Mind your step. The dead don’t sleep well around here.": "Salvē in {p}. Gradūs tuōs cavē. Mortuī hīc nōn bene dormiunt.",
"At night the ghosts walk and the old bones rattle. Read the stones if you like. Just be quick.": "Noctū larvae ambulant et ossa vetera crepitant. Lapidēs lege, sī vīs. Sed celeriter.",
"Something glints between the old stones…": "Aliquid inter lapidēs veterēs micat…",
"You found something left behind by a mourner long ago.": "Aliquid invēnistī quod lūgēns quīdam ōlim relīquit.",
"🪦 You read the old gravestone:": "🪦 Lapidem sepulcrālem veterem legis:",
"“Here lies Old Tom. He finally finished his book.”": "“Hīc iacet Senex Tom. Tandem librum suum fīnīvit.”",
"“She taught a whole village to read. Rest well, teacher.”": "“Tōtum vīcum legere docuit. Bene requiēsce, magistra.”",
"“Gone fishing. Back never.”": "“Piscātum abiit. Numquam rediit.”",
"“Beloved grandfather, terrible singer.”": "“Avus cārissimus, cantor pessimus.”",
"“He knew a word for everything except goodbye.”": "“Verbum omnis reī nōverat praeter ‘valē’.”",
"“Brave, kind, and always late.”": "“Fortis, benignus, semper tardus.”",
"“Here rests a baker. The town still smells of her bread.”": "“Hīc requiēscit pistrīx. Oppidum adhūc pānem eius olet.”",
"“The words fade. The love does not.”": "“Verba ēvānēscunt. Amor nōn.”",
"“Don’t dig. Really. Don’t.”": "“Nōlī fodere. Vērē. Nōlī.”",
"There are no shrines in the wild parts of the land, but pilgrim priests walk those roads. They can wake the fallen.": "In partibus ferīs terrae sacella nūlla sunt, sed sacerdōtēs peregrīnī illās viās ambulant. Cadūcōs excitāre possunt.",
"Put your gold in the bank! If your party falls, you only lose the gold you carry. And it earns interest.": "Aurum tuum in argentāriā pōne! Sī comitēs cadunt, sōlum aurum quod fers āmittis. Et faenus parit.",
"Sailors say a ghost ship drifts on the open sea. Board it if you dare!": "Nautae dīcunt nāvem larvālem in apertō marī errāre. Cōnscende, sī audēs!",
"There’s a whirlpool in the {p}. Some say a whole kingdom lives under it.": "In {p} vertex est. Quīdam dīcunt tōtum rēgnum sub eō habitāre.",
"Ancient temples stand in the wild lands of the north and south. The Hero’s own gear is sealed inside.": "Templa antīqua in terrīs ferīs septentriōnum et merīdiēī stant. Ipsa arma Hērōis intus clausa sunt.",
"Tired? Make camp anywhere on the road. Your friends love a good campfire.": "Fessus? Ubīque in viā castra pōne. Amīcī tuī ignem bonum amant.",
"Whipping thorns on one foe.": "Spīnae verberantēs in ūnum hostem.",
"Heals one friend with flowers and green light.": "Ūnum amīcum flōribus et lūce viridī sānat.",
"The ground heaves under every foe.": "Terra sub omnibus hostibus tremit.",
"A popping flask of fire on one foe.": "Ampulla ignis crepitāns in ūnum hostem.",
"Stinging drops on every foe.": "Guttae pungentēs in omnēs hostēs.",
"A big heal for the whole party.": "Magna medicīna omnibus comitibus.",
"A leap and a strike on one foe.": "Saltus et ictus in ūnum hostem.",
"A spinning sweep that hits every foe.": "Verriculum versātum quod omnēs hostēs ferit.",
"Drops from the sky like lightning on one foe.": "Ē caelō ut fulmen in ūnum hostem cadit.",
"Heals {n} HP. You have {n}.": "{n} PV sānat. {n} habēs.",
"Restores {n} MP. You have {n}.": "{n} PM reddit. {n} habēs.",
"Cures poison. You have {n}.": "Venēnum sānat. {n} habēs.",
"Wakes a fallen ally with half their HP. You have {n}.": "Socium cadūcum cum dīmidiō PV excitat. {n} habēs.",
"You found <b>{n} × {p}</b>!": "<b>{n} × {p}</b> invēnistī!",
"A monster dropped a {p}!": "Mōnstrum {p} relīquit!",
"Hire {p} ({n} gold)": "Condūc {p} ({n} aureī)",
"{p} the {p}: The forests are sick, and so is the world. I can heal you, and the earth itself will fight beside us.": "{p} {p}: Silvae aegrōtant, et mundus quoque. Tē sānāre possum, et ipsa terra nōbīscum pugnābit.",
"{p} the {p}: Fire flasks, healing tonics, and only a few explosions a week. Interested?": "{p} {p}: Ampullae ignis, pōtiōnēs sānantēs, et paucī tantum fragōrēs per hebdomadem. Placetne?",
"🌙 Night falls. Shops close until morning.": "🌙 Nox cadit. Tabernae ad māne clauduntur.",
"☀️ Morning! The shops are open again.": "☀️ Māne est! Tabernae iterum apertae sunt.",
"🌙 The shop is closed for the night.": "🌙 Taberna noctū clausa est.",
"🌙 The smithy is closed for the night.": "🌙 Fabrica noctū clausa est.",
"🌙 The bank is closed for the night.": "🌙 Argentāria noctū clausa est.",
"🌙 The church is closed for the night.": "🌙 Ecclēsia noctū clausa est.",
"🌙 The Chronicle House is closed for the night.": "🌙 Domus Chronicae noctū clausa est.",
"🌙 {p}’s house is closed for the night.": "🌙 Domus {p} noctū clausa est.",
"Come back in the morning. The tavern and the inn are still open.": "Māne redī. Caupōnae adhūc apertae sunt.",
"We’re closed for the night. Come back in the morning!": "Noctū clausī sumus. Māne redī!",
"At night the shops close. Only the tavern and the inn stay open until morning.": "Noctū tabernae clauduntur. Sōlae caupōnae ad māne apertae manent.",
"Innkeeper: Welcome, traveler! Rest your feet. A warm bed is waiting for you.": "Caupōna: Salvē, viātor! Pedēs requiēsce. Lectus calidus tē exspectat.",
"Shopkeeper: Welcome! Herbs, tonics, feathers… have a look around.": "Tabernārius: Salvē! Herbae, pōtiōnēs, pennae… circumspice.",
"Blacksmith: Need a sharper blade or thicker armor? You came to the right place.": "Faber: Gladiō acūtiōre aut lōrīcā crassiōre egēs? Ad rēctum locum vēnistī.",
"Traveler: The beds here are soft as clouds. I sleep like a log every time.": "Viātor: Lectī hīc mollēs ut nūbēs sunt. Semper ut truncus dormiō.",
"Guest: A night at the inn heals everyone and wakes you up bright and early.": "Hospes: Nox in caupōnā omnēs sānat et tē māne vegetum excitat.",
"Customer: Herbs work in battle too. I never leave town without a few.": "Emptor: Herbae etiam in pugnā prōsunt. Numquam sine paucīs ex oppidō exeō.",
"Soldier: Better armor means monsters hit softer. Worth every coin!": "Mīles: Lōrīca melior significat mōnstra mollius ferīre. Omnī nummō digna est!",
"{p}: We’re closed for the night. Come back in the morning!": "{p}: Noctū clausī sumus. Māne redī!",
"🛢️ The barrel is empty.": "🛢️ Dōlium vacuum est.",
"🛢️ You look inside the barrel…": "🛢️ In dōlium īnspicis…",
"Just a few old apples. You leave them for the horses.": "Pauca māla vetera tantum. Ea equīs relinquis.",
"Only rainwater inside. A frog looks up at you.": "Sōla aqua pluviālis intus. Rāna tē suspicit.",
"Empty, except for a very surprised spider.": "Vacuum, praeter arāneam valdē attonitam.",
"Nothing but sawdust and a smell of pickles.": "Nihil nisi scobis et odor cucumerum conditōrum.",
"🪣 You peer down the well. Plop! A pebble falls a long way down.": "🪣 In puteum dēspicis. Plop! Calculus longē dēcidit.",
"🪣 Cool, clear water. You see your own face looking back up.": "🪣 Aqua frīgida et clāra. Faciem tuam tē suspicientem vidēs.",
"🪣 Someone dropped a coin in here for luck. It’s far too deep to reach.": "🪣 Aliquis hīc nummum prō fortūnā iēcit. Longē altius est quam ut attingās.",
"🪣 A rope ladder hangs down into the dark. Water echoes somewhere below.": "🪣 Scālae fūneae in tenebrās dēpendent. Aqua alicubi īnfrā resonat.",
"🧗 Climb down": "🧗 Dēscende",
"You climb down the rope ladder into a cool, damp cave.": "Per scālās fūneās in spēluncam frīgidam et ūmidam dēscendis.",
"A stream trickles into a quiet pond. Was that a chest in the shadows?": "Rīvus in stagnum quiētum fluit. Erātne arca in umbrīs?"
});
GT_BOOKS.la.ready = false;
